"""Scoped receiving job: only repository-indexed files, never execute uploads."""

import json
import shutil
import stat
import tarfile
import zipfile
from pathlib import Path

from pu_toolbox.utils.serialization import file_hash

ROOT = Path(__file__).resolve().parents[2]
WORK = Path(__file__).resolve().parent
FOUR_INDEX = ROOT / "docs/research/pu_survey/data/p1_4r_split_artifacts_index_20261014.json"
ADNI_INDEX = ROOT / "docs/research/pu_survey/data/adni_split_artifacts_index_20261012.json"


def stable_identity(path):
    before = path.stat()
    digest = file_hash(path)
    after = path.stat()
    if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
        raise ValueError(f"Input changed while hashing: {path.name}")
    return {"file": path.name, "bytes": after.st_size, "sha256": digest}


def receive_tar(path, dataset, entry, destination):
    identity = stable_identity(path)
    expected_archive = entry["archive"]
    if any(identity[key] != expected_archive[key] for key in ("file", "bytes", "sha256")):
        raise ValueError(f"Archive identity mismatch: {dataset}")
    expected = {
        f"{dataset}/{split}/{name}": record
        for split, split_entry in entry.items() if split != "archive"
        for name, record in split_entry["files"].items()
    }
    destination.mkdir(parents=True, exist_ok=True)
    with tarfile.open(path, "r:") as archive:
        members = archive.getmembers()
        names = [m.name for m in members]
        if len(names) != len(set(names)) or set(names) != set(expected):
            raise ValueError(f"Unexpected/missing/duplicate tar member: {dataset}")
        for member in members:
            if not member.isfile() or member.issparse() or member.size != expected[member.name]["bytes"]:
                raise ValueError(f"Non-regular or incorrect-sized member: {member.name}")
        for member in members:
            target = destination / member.name
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.extractfile(member) as src, target.open("xb") as dst:
                shutil.copyfileobj(src, dst)
            if file_hash(target) != expected[member.name]["sha256"]:
                raise ValueError(f"Extracted member hash mismatch: {member.name}")
    if stable_identity(path) != identity:
        raise ValueError(f"Archive changed while extracting: {dataset}")
    return {**identity, "members_checked": len(members), "repository_index_matched": True}


def main():
    reference_four = json.loads(FOUR_INDEX.read_text())
    reference_adni = json.loads(ADNI_INDEX.read_text())
    source_zip = ROOT / "p1_4r_20261004.zip"
    zip_identity = stable_identity(source_zip)
    wrapper = "p1_4r_20261014/"
    expected_names = {wrapper, wrapper + "review_report.json", wrapper + "split_artifacts_index.json"}
    expected_names.update(wrapper + entry["archive"]["file"] for entry in reference_four["datasets"].values())
    four_archives = WORK / "archives_four"
    four_archives.mkdir()
    with zipfile.ZipFile(source_zip) as archive:
        members = archive.infolist()
        if len(members) != len(expected_names) or {m.filename for m in members} != expected_names:
            raise ValueError("ZIP wrapper inventory differs from expected four-dataset handoff")
        if sum(m.file_size for m in members) > 1024**3:
            raise ValueError("ZIP wrapper exceeds bounded handoff size")
        for member in members:
            if member.filename == wrapper:
                if not member.is_dir():
                    raise ValueError("Wrapper entry must be a directory")
                continue
            mode = stat.S_IFMT(member.external_attr >> 16)
            if member.flag_bits & 1 or member.is_dir() or mode not in (0, stat.S_IFREG):
                raise ValueError("Encrypted/non-regular ZIP wrapper member")
            target = four_archives / member.filename.removeprefix(wrapper)
            with archive.open(member) as src, target.open("xb") as dst:
                shutil.copyfileobj(src, dst)
    if stable_identity(source_zip) != zip_identity:
        raise ValueError("ZIP changed while receiving")
    delivered_four = json.loads((four_archives / "split_artifacts_index.json").read_text())
    if delivered_four != reference_four:
        raise ValueError("ZIP index differs semantically from published repository index")
    delivered_adni = ROOT / "split_artifacts_index.json"
    if json.loads(delivered_adni.read_text()) != reference_adni:
        raise ValueError("Uploaded ADNI index differs semantically from published index")
    adni_archives = WORK / "archives_adni"
    adni_archives.mkdir()
    with (ROOT / "adni-splits.tar").open("rb") as src, (adni_archives / "adni-splits.tar").open("xb") as dst:
        shutil.copyfileobj(src, dst)
    reports = {}
    for dataset, entry in reference_four["datasets"].items():
        reports[dataset] = receive_tar(four_archives / entry["archive"]["file"], dataset, entry, WORK / "splits_four")
    reports["adni"] = receive_tar(adni_archives / "adni-splits.tar", "adni", reference_adni["datasets"]["adni"], WORK / "splits_adni")
    report = {
        "scope": "repository-anchored receipt and safe scoped unpacking, not semantic acceptance or human signoff",
        "zip": zip_identity, "archives": reports,
        "four_index": {"published_file_sha256": file_hash(FOUR_INDEX), "received_file_sha256": file_hash(four_archives / "split_artifacts_index.json"), "json_equal": True},
        "adni_index": {"published_file_sha256": file_hash(ADNI_INDEX), "received_file_sha256": file_hash(delivered_adni), "json_equal": True},
        "split_files_received": sum(r["members_checked"] for r in reports.values()),
        "uploaded_code_executed": False, "historical_files_overwritten": False,
    }
    (WORK / "receipt_integrity.json").write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
